import{messages}from'./messages.mjs';const $=id=>document.getElementById(id);
if(typeof BigInt==='function'){
const {createController,FIELDS}=await import('./core.mjs');const controller=createController(document.documentElement.lang==='en'?'en':'zh-Hant');
function render(){const s=controller.state(),m=messages[s.language];document.documentElement.lang=s.language;document.title=m.title+' · Gloss Tools';document.querySelector('meta[name="description"]').content=m.description;for(const el of document.querySelectorAll('[data-copy]'))el.textContent=m[el.dataset.copy];$('home').href='https://glossquote.com/'+(s.language==='en'?'en/':'')+'index.html';$('language').textContent=s.language==='en'?'繁體中文':'English';$('language').lang=s.language==='en'?'zh-Hant':'en';for(const key of[...FIELDS,'operator'])$(key).value=s.raw[key];$('output').hidden=s.status!=='success';$('snippet').value='';$('sign-note').hidden=true;for(const k of['a','b','line','unreduced','gcd','result','mixed'])$(k).textContent='';$('summary-errors').replaceChildren();const errors=s.status==='error'?s.result.errors:{};for(const key of FIELDS){const error=errors[key];$('error-'+key).textContent=error?m.errors[error]:'';$(key).setAttribute('aria-invalid',String(Boolean(error)));}for(const[key,error]of Object.entries(errors)){const li=document.createElement('li'),a=document.createElement('a');a.href='#'+(key==='schema'?'reset':key);a.textContent=(m[key]?m[key]+': ':'')+m.errors[error];a.addEventListener('click',e=>{e.preventDefault();$(key==='schema'?'reset':key).focus();});li.append(a);$('summary-errors').append(li);}$('summary-errors').hidden=!Object.keys(errors).length;$('status').textContent=m[s.status==='error'?'errorStatus':s.status];if(s.status==='success'){for(const k of['a','b','line','unreduced','gcd','result','mixed'])$(k).textContent=s.result[k];$('snippet').value=s.result.summary;$('sign-note').hidden=!s.result.signNormalized;}}
for(const key of FIELDS)$(key).addEventListener('input',()=>{controller.edit(key,$(key).value);render();});$('operator').addEventListener('change',()=>{controller.edit('operator',$('operator').value);render();});$('form').addEventListener('submit',e=>{e.preventDefault();const s=controller.calculate();render();const first=s.status==='error'?Object.keys(s.result.errors)[0]:null;$(first?(first==='schema'?'reset':first):'generate').focus();});$('reset').addEventListener('click',()=>{controller.reset();render();$('reset').focus();});$('language').addEventListener('click',()=>{controller.language(controller.state().language==='en'?'zh-Hant':'en');render();$('language').focus();});window.addEventListener('pageshow',()=>{controller.reconcile();render();});$('boot-status').hidden=true;$('generate').disabled=false;$('reset').disabled=false;render();
}
